import json
import re

# Parse input JSON
try:
    data = json.loads(input.get('customer_data', '{}'))
except:
    data = {}

# Validation results
errors = []
warnings = []

# Required fields check
required_fields = ['name', 'email', 'age']
for field in required_fields:
    if not data.get(field):
        errors.append(f'Missing required field: {field}')

# Email format validation
email = data.get('email', '')
if email and not re.match(r'^[\w\.-]+@[\w\.-]+\.\w+$', email):
    errors.append('Invalid email format')

# Age validation
age = data.get('age')
if age:
    try:
        age_int = int(age)
        if age_int < 18:
            warnings.append('Customer is under 18')
        elif age_int > 100:
            warnings.append('Age seems unusually high')
    except:
        errors.append('Age must be a number')

# Country validation
country = data.get('country', '')
valid_countries = ['US', 'CA', 'UK', 'AU', 'IN']
if country and country not in valid_countries:
    warnings.append(f'Country {country} requires manual review')

# Determine validation status
if errors:
    status = 'invalid'
elif warnings:
    status = 'needs_review'
else:
    status = 'valid'

output = {
    'customer_data': data,
    'validation_status': status,
    'errors': errors,
    'warnings': warnings,
    'is_valid': len(errors) == 0
}
